EXPECTED = ["LY-454","LY-455","LY-457","LY-458","LY-501","LY-502","LY-503","LY-504","LY-505","LY-506",
            "LY-507","LY-508","LY-509","LY-510","LY-511","LY-512","LY-513","LY-514","LY-515","LY-516"]

def main():
    assert sorted(CASES.keys()) == sorted(EXPECTED), "case set mismatch"
    assert len(CASES) == 20
    os.makedirs(OUT, exist_ok=True)
    written = 0
    cm = ru = di = 0
    for cid in EXPECTED:
        rec = CASES[cid]
        assert rec["case_id"] == cid
        assert set(rec.keys()) == {"case_id","prediction_text","basis","confidence","trigger"}, cid
        assert 0.0 <= rec["confidence"] <= 1.0
        t = rec["trigger"]
        assert set(t.keys()) == {"changed_main","reserve_used","disputed","reason"}, cid
        assert all(isinstance(t[k], bool) for k in ("changed_main","reserve_used","disputed"))
        assert isinstance(t["reason"], str) and t["reason"]
        cm += t["changed_main"]; ru += t["reserve_used"]; di += t["disputed"]
        path = os.path.join(OUT, cid + ".json")
        with open(path, "x", encoding="utf-8") as f:
            json.dump(rec, f, ensure_ascii=False, indent=1)
        written += 1
    # verify each file round-trips
    for cid in EXPECTED:
        with open(os.path.join(OUT, cid + ".json"), encoding="utf-8") as f:
            back = json.load(f)
        assert back["case_id"] == cid
    print(f"written={written} changed_main={cm} reserve_used={ru} disputed={di}")

if __name__ == "__main__":
    main()
